import { jsx as _jsx } from "react/jsx-runtime";
import { coordLabelWidth, splitString } from '../util.js';
import SequenceDisplay from './SequenceDisplay.js';
// An up/downstream flank contributes a segment only when its sequence was
// fetched; `transform` applies e.g. the cDNA lower-casing. Returns 0 or 1
// segments so it can be spread into a segment list.
export function flankSegment(key, str, color, transform = s => s) {
    return str ? [{ key, str: transform(str), color }] : [];
}
// Lays a list of colored segments (upstream, exons/UTRs/introns, downstream)
// into <SequenceDisplay> rows, threading the running row-fill remainder and
// genomic coordinate across segments so rows and coordinate labels stay
// continuous. Segments that produce no visible characters are skipped. strand
// `mult` is +1 (forward) or -1 (reverse, where coordinates count down).
export function renderSequenceSegments({ segments, model, mult, coordStart, onHoverBase, }) {
    const { charactersPerRow, showCoordinates } = model;
    // computed across every segment up front: the segments share rows, so each
    // one has to pad its labels to the whole panel's width, not its own
    const labelWidth = coordLabelWidth({
        firstCoord: coordStart,
        totalLength: segments.reduce((a, b) => a + b.str.length, 0),
        charactersPerRow,
        strand: mult,
    });
    let currCoord = coordStart;
    let currRemainder = 0;
    const nodes = [];
    for (const { key, str, color } of segments) {
        const { segments: chunks, remainder } = splitString({
            str,
            charactersPerRow,
            currRemainder,
            showCoordinates,
        });
        if (chunks.length) {
            nodes.push(_jsx(SequenceDisplay, { model: model, color: color, strand: mult, coordStart: currCoord, labelWidth: labelWidth, remainder: currRemainder, chunks: chunks, onHoverBase: onHoverBase }, key));
            currRemainder = remainder;
            currCoord += str.length * mult;
        }
    }
    return nodes;
}
